'use strict';
const SAVE_KEY='ouat-pass5-slice-save-v1', META_KEY='ouat-pass5-slice-profile-v1'; // Keep P5 save key for seamless migration
const byId=id=>document.getElementById(id), root=byId('screen'), sheetRoot=byId('overlay-root');
const M=Object.fromEntries(STORY.map(m=>[m.id,m]));
const ART={shop:'shop',woods:'woods',tracks:'tracks',red:'red',wolf:'wolf',kingdom:'landscape',landscape:'landscape',village:'village',shadow:'shadow', cloud:'cloud',ledger:'ledger',giant:'giant',clock:'clock',seed:'seed',crow:'crow',bridge:'bridge',jack:'jack',palace:'palace',ballroom:'ballroom',glass:'glass',cabinet:'cabinet',invitation:'invitation',cinderella:'cinderella',servants:'servants',march:'march',bakery:'bakery',tunnels:'tunnels',festival:'festival',sugar:'sugar',archive:'archive',preservation:'preservation',catalog:'catalog',court:'court',margin:'margin',ink:'ink',orders:'orders',page:'page',king:'king',echo:'echo',engine:'engine',bookshop:'shop', 'bell-tower':'bell-tower','silver-path':'silver-path','cloud-lantern':'cloud-lantern','midnight-clock':'midnight-clock','sugar-lights':'sugar-lights','archive-glow':'archive-glow','court-rays':'court-rays','margin-stars':'margin-stars','last-chime':'last-chime'};
let s=null,meta={demoRuns:0,completedLocal:[],atlas:[]},setupTrait='curious',uiTab='clues',toastCounter=0,saveAvailable=true,overlayType=null;
let recoveryIssue='',returnFocus=null,lastRenderedScene='',pendingFocus=null,saveChangedAt=0,setupPath='sleuth';
function safeRaw(key){try{return localStorage.getItem(key)}catch{return null}}
function read(key){try{return JSON.parse(safeRaw(key))}catch{return null}}
function write(key,data){try{localStorage.setItem(key,JSON.stringify(data));return true}catch{saveAvailable=false;return false}}
const validScene=(x)=>typeof x==='string'&&/^(A\d+(?:-[A-Z]\d+|-[0-9]+)|HUB-\d+|REC-\d+|END-E\d{2})-S0[1-5]$/.test(x)&&M[x.slice(0,-4)];
function defaultGameBase(name,trait){return {version:1,name:(name||'Traveler').trim().slice(0,24)||'Traveler',trait:trait||'curious',scene:'A0-01-S01',stats:{courage:2,wit:2,heart:2},rels:{red:0,wolf:0,courier:0,jack:0,bram:0,cinderella:0,nell:0,pip:0,hansel:0,gretel:0,taffy:0,tern:0,assistant:0,quill:0},flags:{},seen:{},interactions:{},miniGames:{},depthChoices:{},depthOpen:null,branchOpen:null,branchHistory:{},legacyRun:{history:{},open:null},progression:window.OUATLitRPG?.base(trait==='brave'?'scout':trait==='kind'?'guardian':'sleuth')||null,evidence:{},items:['Journal'],notes:[],theory:null,attempts:{},startedAt:Date.now(),lastSavedAt:null,complete:false,decisions:0};}
function atlasTier(){
 const atlas=Array.isArray(meta.atlas)?meta.atlas:[];
 const unique=new Set(atlas.map(x=>x.ending));
 if(!atlas.length)return 1; // L01 = fresh story
 let tier=2;
 if(unique.size>=2)tier=3;
 if(unique.size>=3&&atlas.some(x=>x.thiefProven))tier=4;
 if(unique.size>=4&&atlas.some(x=>x.missingChime))tier=5;
 return tier;
}
function defaultGame(name,trait){
 const st=defaultGameBase(name,trait);
 if(meta.atlas?.length){st.flags.legacy_verified=true;st.flags.legacy_tier=atlasTier();st.flags.legacy_source='completed_atlas';st.notes.push({at:'Living Atlas',text:'A neighboring telling remains complete. A memory can give you a question to ask. It cannot prove what happened here or make someone your friend.'});}
 return st;
}
function recordAtlasOutcome(){
 if(!s?.flags?.act8_complete)return;
 const ending=s.flags.a8_ending_selected;
 if(!/^E(0[1-9]|1[0-2])$/.test(ending||''))return;
 meta.atlas||=[];
 const key=s.startedAt+'-'+ending;
 if(meta.atlas.some(x=>x.key===key))return;
 meta.atlas.push({key,ending,firstRoad:s.flags.chosen_road||'woods',name:s.name,epilogue:s.flags.a8_epilogue_style||'community',date:new Date().toISOString(),thiefProven:!!s.flags.a6_single_thief_proven,missingChime:!!s.evidence['EV-C15']&&!!s.evidence['EV-C17'],proofCount:Object.keys(s.evidence).length,notes:s.notes.slice(-8).map(x=>x.text).filter(Boolean)});
 // Completed histories remain separate. Never copy old testimony into current evidence.
 meta.atlas=meta.atlas.slice(-100); save();
}
function renderLivingAtlas(){
 const atlas=meta.atlas||[];
 const cards=atlas.slice().reverse().map((e,i)=>`<div class="entry"><div class="entry-title">${esc(e.ending+' · '+(endById[e.ending]?.name||'Ending'))}</div><p>${esc(e.firstRoad==='reflection'?'Reflection Road':e.firstRoad==='cloud'?'Cloudreach':e.firstRoad==='palace'?'Palace of Hours':'Neverafter Woods')} · ${esc(e.date.slice(0,10))} · ${esc(e.epilogue)} perspective</p><p class="muted small">Independent completed possibility. This history is not erased by starting another.</p></div>`).join('');
 markupSheet('The Living Atlas',`<p class="muted">${atlas.length} completed tellings · ${new Set(atlas.map(x=>x.ending)).size} unique ending families · Legacy Tier L0${atlasTier()}</p>${cards||'<p>No Book One ending has been recorded. Finish Act VIII to earn the first.</p>'}<p class="muted small">Memories unlock questions and additional routes, not automatic evidence, consent, or friendship.</p>${OUATLegacy.recordsHTML(meta,esc)}`);
 sheetRoot.querySelectorAll('[data-legacy-buy]').forEach(b=>b.onclick=()=>{if(OUATLegacy.purchase(meta,b.dataset.legacyBuy)){save();renderLivingAtlas()}});
}
function renderBookOneFinish(){
 recordAtlasOutcome();
 const spec=endById[s.flags.a8_ending_selected]||endById.E01;
 byId('toast').className='';
 root.innerHTML=`<main class="screen-cover" style="justify-content:flex-end"><div class="cover-heading"><div class="cover-logo">📖 ✦</div><h1 style="font-size:clamp(32px,8.5vw,49px)">${esc(spec.name)}</h1><small>BOOK ONE · COMPLETE · ${esc(spec.id)}</small></div><div class="cover-bottom"><div class="outcome"><h3>The ending you earned remains yours.</h3><p>${esc(spec.world)}</p><p>${esc(s.flags.a8_epilogue_style==='bookshop'?spec.epB:spec.epA)}</p><p><strong>Clues:</strong> ${Object.keys(s.evidence).length} · <strong>Decisions:</strong> ${s.decisions}</p></div><div class="notice">✓ Current theft machine stopped<br>✓ Freely chosen outcome preserved<br>✓ Official public record corrected<br>✓ Living Atlas entry saved</div><div class="stack"><button class="btn primary" id="finishNew">◇ Begin New Telling + <span class="arrow">❯</span></button><button class="btn" id="finishAtlas">📖 View the Living Atlas</button><button class="btn" id="finishJournal">Review Your Journal</button><button class="btn subtle" id="finishTitle">Title Screen</button></div><p class="save-note">A new telling is another valid history—not a rewind. Reflection Road is now available. Other routes depend on earned Atlas achievements.</p></div></main>`;
 byId('finishAtlas').onclick=renderLivingAtlas;
 byId('finishJournal').onclick=()=>showSheet('journal');
 byId('finishTitle').onclick=renderTitle;
 byId('finishNew').onclick=()=>{if(!confirm('Begin a neighboring telling? This replaces your current in-progress save, but your completed ending remains permanently in the Living Atlas on this device.'))return;meta.demoRuns++;save();renderSetup()};
}
function load(){
 const primary=read(SAVE_KEY);let raw=null;
 const m=read(META_KEY)||read(META_KEY+'.lastGood')||read(SAVE_KEY+'.profileGood');
 try{meta=OUATSave.sanitizeMeta(m||{})}catch{recoveryIssue='The profile needs recovery. Your adventure remains available.';meta={demoRuns:0,completedLocal:[],atlas:[]}}
 if(primary){try{raw=OUATSave.sanitizeGame(primary,validScene)}catch(e){recoveryIssue='Primary save could not be loaded: '+e.message}}
 else if(safeRaw(SAVE_KEY))recoveryIssue='Current save is damaged. A recovery copy may exist.';
 if(!raw){for(const candidate of OUATSave.recoveryCandidates(localStorage,SAVE_KEY,validScene).filter(c=>c.key!==SAVE_KEY)){raw=candidate.game;recoveryIssue='Recovered a healthy copy from '+candidate.label+'. Export a backup to protect it.';break}}
 if(raw){s=raw;s.rels=Object.assign({red:0,wolf:0,courier:0,jack:0,bram:0,cinderella:0,nell:0,pip:0,hansel:0,gretel:0,taffy:0,tern:0,assistant:0,quill:0},s.rels||{});s.seen||={};s.interactions||={};s.miniGames||={};s.depthChoices||={};s.depthOpen||=null;s.legacyRun=OUATLegacy.normRun(s.legacyRun,s.scene);s.attempts||={};s.notes||=[];s.items||=['Journal'];s.progression=OUATLitRPG.normalize(s.progression,s.trait);if(raw.complete&&raw.scene.startsWith('A2-01-S0')&&!raw.flags.act2_complete){s.complete=false;s.scene='A2-01-S01';s.flags.p7_resumed=true;save();}if(raw.complete&&raw.scene.startsWith('HUB-02-S0')&&!raw.flags.act3_complete){s.complete=false;s.flags.act2_complete=true;s.scene='HUB-02-S05';s.flags.p8_resumed=true;save();}if(raw.complete&&raw.scene.startsWith('HUB-03-S0')&&!raw.flags.act4_complete){s.complete=false;s.flags.act3_complete=true;s.scene='HUB-03-S05';s.flags.p9_resumed=true;save();}if(raw.complete&&raw.scene.startsWith('HUB-04-S0')&&!raw.flags.act5_complete){s.complete=false;s.flags.act4_complete=true;s.scene='HUB-04-S05';s.flags.p10_resumed=true;save();}if(raw.complete&&raw.scene.startsWith('HUB-05-S0')&&!raw.flags.act6_complete){s.complete=false;s.flags.act5_complete=true;s.scene='HUB-05-S05';s.flags.p11_resumed=true;save();}if(raw.complete&&raw.scene.startsWith('HUB-06-S0')&&!raw.flags.act7_complete){s.complete=false;s.flags.act6_complete=true;s.scene='HUB-06-S05';s.flags.p12_resumed=true;save();}if(raw.complete&&raw.scene.startsWith('HUB-07-S0')&&!raw.flags.act8_complete){s.complete=false;s.flags.act7_complete=true;s.scene='HUB-07-S05';s.flags.p13_resumed=true;save();}}}
function save(){
 try{
  meta=OUATSave.sanitizeMeta(meta);
  if(s){s.schemaVersion=2;s.lastSavedAt=new Date().toISOString();OUATSave.saveSnapshot(localStorage,SAVE_KEY,s,meta,validScene)}
  localStorage.setItem(META_KEY,JSON.stringify(meta));localStorage.setItem(META_KEY+'.lastGood',JSON.stringify(meta));
  saveChangedAt=Date.now();saveAvailable=true;return true;
 }catch(error){console.warn('Local save unavailable',error);saveAvailable=false;return false}
}
function esc(v){return String(v==null?'':v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;')}
function textOf(v){const raw=typeof v==='function'?v(s):v;return String(raw||'').replaceAll('{name}',s?esc(s.name):'Traveler')}
function paras(raw){return textOf(raw).split(/\n\n+/).map(x=>'<p>'+esc(x).replaceAll('&lt;strong&gt;','<strong>').replaceAll('&lt;/strong&gt;','</strong>')+'</p>').join('')}
function img(name){return 'assets/'+(ART[name]||'woods')+'.webp'}
function titleSection(){return `<div class="cover-heading"><div class="cover-logo">✧ 📖 ✧</div><h1>Once Upon<br>Another Time</h1><small class="caps">THE THIRTEENTH BELL</small></div>`}
function renderTitle(){document.documentElement.style.setProperty('--cover-art',`url(\"${img('bell-tower')}\")`);window.OUATSound?.transitionTo('bookshop');lastRenderedScene='';s=s||null;document.title='Once Upon Another Time — The Thirteenth Bell';root.innerHTML=`<main class="screen-cover">${titleSection()}<div class="cover-bottom"><div style="text-align:center;margin:0 0 13px;color:#ffe1a6;font-family:Georgia,serif;font-size:21px">A fairy-tale mystery RPG</div><p class="cover-intro">Explore three fairy-tale kingdoms, uncover forged stories, defend the truth at court, and gather your allies for the final confrontation.</p><div class="stack">${s?'<button class="btn primary" id="titleContinue"><strong>Continue Your Adventure</strong><span class="arrow">❯</span></button>':''}<button class="btn ${s?'':'primary'}" id="titleNew"><strong>${s?'Start a New Adventure':'Begin Adventure'}</strong><span class="arrow">✧</span></button>${meta.atlas?.length?'<button class="btn" id="titleAtlas">📖 Living Atlas · '+meta.atlas.length+' completed</button>':''}<button class="btn subtle" id="titleGuide">📖 Guided Tutorial</button><button class="btn subtle" id="titleSettings">⚙ Settings & Accessibility</button><button class="btn subtle" id="titleRecover">🛟 Backups & Recovery</button></div>${meta.completedLocal?.length?`<div class="save-note">Completed local cases: ${meta.completedLocal.map(x=>({woods:'🌲 Woods',cloud:'☁ Cloudreach',palace:'🕰 Palace'})[x]||x).join(' · ')}</div>`:''}${recoveryIssue?`<div class="notice" role="status">${esc(recoveryIssue)}</div>`:''}<div class="cover-ver">BOOK ONE · THE THIRTEENTH BELL · STORYBOOK ADVENTURE</div><p class="privacy-link"><a href="privacy.html">For families: How this game uses your data</a></p><div class="legacy-link">Full eight-act campaign · twelve gated endings · 25 replay-exclusive excursions · 26 hands-on story puzzles. Scene art and optional music have been added. Final phone checks and independent artwork-rights review are still needed before a commercial launch.</div></div></main>`;
 if(s)byId('titleContinue').onclick=()=>renderStory();byId('titleNew').onclick=()=>{if(s&&!confirm('Begin a fresh telling? This replaces the current local save. Completed Atlas endings remain saved, and a new telling may open earned routes.'))return;renderSetup()};if(byId('titleAtlas'))byId('titleAtlas').onclick=renderLivingAtlas;byId('titleGuide').onclick=()=>showSheet('guide');byId('titleSettings').onclick=()=>showSheet('settings');byId('titleRecover').onclick=()=>showSheet('recovery');}
function renderSetup(){root.innerHTML=`<main class="panel-screen"><button class="circle" id="setupBack" aria-label="Back to title">‹</button><h1 class="panel-heading">Create Your Story</h1><div class="panel"><label for="heroName" class="field-label">Choose a story name</label><input id="heroName" class="text-input" maxlength="24" placeholder="Traveler" autocomplete="off" value="Traveler"/><p class="muted small">Pick any made-up name you like. Your story stays on this device. No account needed.</p></div><div class="panel"><h3>Choose a starting trait</h3><p class="muted small">Every trait can solve every important puzzle. Choose the approach that feels most like you.</p><div class="trait-grid"><button class="trait selected" data-trait="curious"><span class="emoji">🔎</span><span class="name">Curious</span><span class="detail">Notice details</span></button><button class="trait" data-trait="brave"><span class="emoji">⚔️</span><span class="name">Brave</span><span class="detail">Face new things</span></button><button class="trait" data-trait="kind"><span class="emoji">♥️</span><span class="name">Kind</span><span class="detail">Hear others</span></button></div></div><div class="panel"><h3>Choose your adventurer build</h3><p class="muted small">Every build can finish every story. Your class changes how you approach optional challenges, not whether anyone must trust you.</p><div class="build-paths"><button class="trait" data-path="scout">⚔ Trail Scout<small>Brave paths</small></button><button class="trait selected" data-path="sleuth">🔎 Archive Sleuth<small>Patterns</small></button><button class="trait" data-path="guardian">♥ Story Guardian<small>People first</small></button></div></div><div class="panel"><div class="serif gold" style="font-size:20px">Your adventure begins in a bookshop…</div><p class="muted">Meet Mistress Quill and Pip the mouse; learn how choices, clues, and theories work; then choose a kingdom and pursue the missing Lantern Keeper across Act II.</p></div><button class="btn primary" id="setupGo">Enter the Midnight Bookshop <span class="arrow">❯</span></button><p class="save-note">Choices and reading progress save automatically on this browser.</p></main>`;
 byId('setupBack').onclick=renderTitle;document.querySelectorAll('[data-trait]').forEach(x=>x.onclick=()=>{setupTrait=x.dataset.trait;document.querySelectorAll('[data-trait]').forEach(y=>y.classList.toggle('selected',y===x))});setupPath=setupTrait==='brave'?'scout':setupTrait==='kind'?'guardian':'sleuth';document.querySelectorAll('[data-path]').forEach(x=>{x.classList.toggle('selected',x.dataset.path===setupPath);x.onclick=()=>{setupPath=x.dataset.path;document.querySelectorAll('[data-path]').forEach(y=>y.classList.toggle('selected',y===x))}});byId('setupGo').onclick=()=>{s=defaultGame(byId('heroName').value,setupTrait);if(setupTrait==='curious')s.stats.wit++;if(setupTrait==='brave')s.stats.courage++;if(setupTrait==='kind')s.stats.heart++;s.progression=OUATLitRPG.base(setupPath);s.items.push('Stitched Map');s.notes.push({at:'A0-01',text:'Your journey began at the Midnight Bookshop.'});save();renderStory()};}
function parts(sceneId){const i=sceneId.lastIndexOf('-S0'),id=sceneId.slice(0,i),stage=+sceneId.slice(i+2);return{id,stage,mission:M[id]}}
function missionProgress(){const p=parts(s.scene),index=STORY.findIndex(x=>x.id===p.id);return {index,total:STORY.length, ...p}}
function applyEffect(e){if(!e)return;let changed=[];
 if(e.flag){s.flags[e.flag]=('value' in e)?e.value:true;changed.push('Your choice is saved')}
 if(e.clue){const data=EVIDENCE_INFO[e.clue];if(!s.evidence[e.clue]){s.evidence[e.clue]={acquiredAt:s.scene,source:e.source||'Direct observation',title:data?.title||e.clue};changed.push('Clue found: '+(data?.title||e.clue))}}
 if(e.item&&!s.items.includes(e.item)){s.items.push(e.item);changed.push('Added to satchel: '+e.item)}
 if(e.stat){let [key,v]=e.stat;s.stats[key]=Math.max(0,Math.min(10,(s.stats[key]||0)+v));changed.push((v>0?'+':'')+v+' '+key)}
 if(e.rel){let [key,v]=e.rel;s.rels[key]=Math.max(-4,Math.min(5,(s.rels[key]||0)+v));changed.push('Your relationship may change')}
 if(e.note){s.notes.push({at:s.scene,text:e.note});changed.push('Added to your journal')}
 if(changed.length)return changed.join(' · ');return '';
}
function addNote(text){if(!text)return;s.notes.push({at:s.scene,text});if(s.notes.length>140)s.notes.shift()}
function openLegacyEpisode(id){if(!OUATLegacy.begin(s,id,parts(s.scene).id,meta))return;save();lastRenderedScene='';renderStory()}
function inspectLegacyEpisode(i){if(!OUATLegacy.inspect(s,i))return;save();lastRenderedScene='';renderStory()}
function chooseLegacyEpisode(i){if(!OUATLegacy.choose(s,i))return;save();lastRenderedScene='';renderStory()}
function finishLegacyEpisode(){const result=OUATLegacy.finish(s,meta);if(!result)return;addNote('A neighboring telling · '+result.e.title+': '+result.text);s.decisions++;save();lastRenderedScene='';renderStory();if(result.firstTime)toast('✦ New Story Spark earned · Living Atlas')}
function advanceSkill(m){const c=window.OUATLitRPG?.CHALLENGES[m.id];if(c&&!s.progression?.checks[m.id]){s.progression.open={id:m.id,step:'choose'};save();lastRenderedScene='';renderStory();return}toStage(m.id,3)}
function resolveSkill(m,method){if(s.progression?.open?.id!==m.id||s.progression.open.step!=='choose')return;const res=OUATLitRPG.resolve(s,m.id,method);if(!res){toast('That ally is not ready to help. Choose another method.');return}save();lastRenderedScene='';renderStory()}
function finishSkill(m){if(s.progression?.open?.id!==m.id||s.progression.open.step!=='result')return;s.progression.open=null;toStage(m.id,3)}
function advanceInteraction(m){
 const interlude=OUATScenes.interludes[m.id];const state=s.interactions||(s.interactions={});
 if(interlude&&!state[m.id]?.done){state[m.id]={active:true,done:false};save();renderStory();return}
 if(window.OUATPuzzles?.has(m.id)&&!s.miniGames?.[m.id]?.done){OUATPuzzles.ensure(s,m.id);save();lastRenderedScene='';renderStory();return}
 const branch=window.OUATBranches?.get(m.id);
 if(branch&&!s.branchHistory?.[m.id]){s.branchOpen={id:m.id,step:'fork'};save();lastRenderedScene='';renderStory();return}
 advanceSkill(m);
}
function chooseBranchRoute(m,i){
 const route=OUATBranches.selectRoute(m.id,i,s);if(!route||s.scene!==m.id+'-S02'||s.branchOpen?.id!==m.id||s.branchOpen?.step!=='fork')return;
 s.branchOpen={id:m.id,step:'challenge',route:i};
 addNote('New route in '+m.title+': '+route.label);
 save();lastRenderedScene='';renderStory();
}
function resolveBranch(m,i){
 const open=s.branchOpen,route=OUATBranches.selectRoute(m.id,open?.route,s),option=route?.options[i];
 if(!route||!option||open?.id!==m.id||open.step!=='challenge')return;
 s.branchOpen={...open,step:'outcome',choice:i};
 s.branchHistory||(s.branchHistory={});
 s.branchHistory[m.id]={route:open.route,label:route.label,result:option[2],text:option[1]};
 addNote('Branch result — '+m.title+': '+option[1]);s.decisions++;
 save();lastRenderedScene='';renderStory();
}
function finishBranch(m){
 if(s.branchOpen?.id!==m.id||s.branchOpen.step!=='outcome')return;
 s.branchOpen=null;advanceSkill(m);
}
function tapMini(id,action,value){
 if(!s||parts(s.scene).id!==id||parts(s.scene).stage!==2)return;
 const result=OUATPuzzles.tap(s,id,action,value);if(!result)return;
 if(result.finished){addNote('Puzzle completed — '+OUATPuzzles.get(id).title+': '+result.feedback);window.OUATSound?.effect('discovery');s.decisions++;}
 save();lastRenderedScene='';renderStory();
}
function hintMini(id){if(!s||parts(s.scene).id!==id)return;OUATPuzzles.hint(s,id);save();lastRenderedScene='';renderStory()}
function helpMini(id){if(!s||parts(s.scene).id!==id)return;
 const result=OUATPuzzles.help(s,id);if(result){addNote('Solved with a hint — '+OUATPuzzles.get(id).title);save();lastRenderedScene='';renderStory()}
}
function finishMini(id){const st=s.miniGames?.[id];if(!st?.done||st.step!=='celebrate'||parts(s.scene).id!==id)return;st.step='complete';save();advanceInteraction(M[id])}
function answerInterlude(m,i){
 const spec=OUATScenes.interludes[m.id],option=spec?.options[i];if(!option)return;
 if(!option[1]){s.interactions[m.id]={active:true,done:false,feedback:option[2]};save();renderStory();return}
 s.interactions[m.id]={active:false,done:true,feedback:option[2]};addNote(option[2]);s.decisions++;save();advanceInteraction(m);
}
function openStoryMoment(id){
 const data=OUATDepth.dialogues[id];if(!data)return;
 const remembered=s.depthChoices?.[id];s.depthOpen={id,step:remembered===0||remembered===1?'reply':'ask',answer:remembered===1?1:0};
 save();lastRenderedScene='';renderStory();
}
function answerStoryMoment(id,i){
 const data=OUATDepth.dialogues[id];if(!data||![0,1].includes(i)||s.depthOpen?.id!==id)return;
 s.depthChoices||(s.depthChoices={});s.depthChoices[id]=i;
 s.depthOpen={id,step:'reply',answer:i};
 addNote('Conversation with '+data.speaker+': '+(i===0?data.label0:data.label1)+' '+(i===0?data.reply0:data.reply1));
 s.decisions++;save();lastRenderedScene='';renderStory();
}
