function inspect(m,i){pendingFocus=i;const seen=s.seen[m.id]||(s.seen[m.id]=[]);if(seen.includes(i)){toast('You already looked here. Keep going whenever you are ready.');return}seen.push(i);const observation=m.observations[i];const note=applyEffect(observation[2]);addNote(observation[1]);s.decisions++;save();renderStory();toast(observation[1].slice(0,110));}
function solvePuzzle(m,i){pendingFocus=i;const a=m.puzzle.answers[i];if(!a[1]){let attempt=s.attempts[m.id]||{count:0};attempt.count++;attempt.hint=a[2];s.attempts[m.id]=attempt;save();renderStory();toast('Try again. Mistakes do not end the story.');return}if(m.puzzle.grant)applyEffect({clue:m.puzzle.grant,source:m.puzzle.source});if(m.puzzle.flag)applyEffect({flag:m.puzzle.flag});addNote(m.puzzle.question+' — '+a[0]);s.attempts[m.id]={count:(s.attempts[m.id]?.count||0),solved:true};advanceInteraction(m);window.OUATSound?.effect('discovery');toast('Puzzle solved · Evidence recorded');}
function choose(m,i){const a=m.choices[i];const message=applyEffect(a[1]);addNote('Choice: '+a[0]);if(m.id==='A8-X03'){s.flags.a8_three_levers_proven=!!s.flags.a8_independent_anchors;s.flags.a8_machine_disabled=!!s.flags.a8_independent_anchors;s.flags.a8_preserved_anchor=true;s.flags.a8_public_protocol='survivor_custodians';s.flags.a8_public_witness_recorded=true;}
 if(m.id==='A8-02'){if(!s.evidence['EV-C15'])applyEffect({clue:'EV-C15',source:'Authenticated tower striker + original independent apprentice copy'});s.flags.a8_public_witness_recorded=true;}
 if(m.id==='A8-03'){s.flags.a8_machine_disabled=!!s.flags.a8_three_levers_proven;s.flags.a8_preserved_anchor=true;}
 if(m.id==='A8-04'){s.flags.a8_public_custody=true;}
 if(m.id==='A1-R10'){s.flags.echo_route_finished=true;}if(m.id==='A8-05'&&s.flags.a8_gate_review==='careful'&&!s.flags.a8_ending_selected){s.scene='A8-05-S02';s.flags.a8_gate_review=null;s.decisions++;save();renderStory();return;}
 if(m.id==='A7-02'){s.flags.a7_affected_permission=s.flags.a7_witness_protocol==='ask_limited'?'limited_test':'withheld';}if(m.id==='A7-03'&&s.flags.a7_coalition_focus==='general'){s.flags.a7_coalition_commitment='limited_general';}if(['A7-04','A7-05','A7-06','REC-10'].includes(m.id)){s.flags.a7_coalition_commitment=m.id;}if(m.id==='REC-06'){s.flags.a7_bell_role_checked=true;}if(m.id==='A5-06'&&(['wolf_possible','jack_possible','cinderella_possible','steward_possible','tern_possible'].includes(s.flags.a5_accusation))){s.flags.a5_public_rumor=true;}if(m.id==='A5-08'&&s.evidence['EV-C14']){s.flags.a5_courier_origin_checked=true;}if(m.id==='A1-W08'){
   if(s.flags.messenger_record==='public_request')s.flags.messenger_record=s.flags.courier_approach==='demand'?'sealed':'limited_public';
   if(s.flags.messenger_record==='sealed'||s.flags.messenger_record==='limited_public')s.flags.courier_statement_recorded=true;
 }
 s.decisions++;s.scene=m.id+'-S04';save();renderStory();if(message)toast(message.slice(0,120));}
