 if(k==='journal'&&has)h=`<button class="btn subtle" id="journalBuild">✦ Character Build · Level ${s.progression?.level||1}</button><p class="small muted">Observations and choices are stored here. The journal never calls a theory a fact.</p><div class="journal-tabs"><button class="tab ${uiTab==='clues'?'active':''}" data-jtab="clues">Clues (${Object.keys(s.evidence).length})</button><button class="tab ${uiTab==='notes'?'active':''}" data-jtab="notes">Notes (${s.notes.length})</button><button class="tab ${uiTab==='games'?'active':''}" data-jtab="games">Puzzles (${Object.values(s.miniGames||{}).filter(x=>x.done).length})</button></div>${uiTab==='games'?Object.entries(s.miniGames||{}).filter(([id,state])=>state.done).map(([id,state])=>`<div class="entry"><div class="entry-title">🎲 ${esc(OUATPuzzles.get(id)?.title||id)}</div><p>${esc(state.help?'Solved with a little help. Great teamwork!':'You solved this puzzle!')}</p></div>`).join('')||'<p>Your solved puzzles will appear here. Take your time and have fun!</p>':uiTab==='clues'?Object.entries(s.evidence).map(([id,e])=>`<div class="entry"><div class="entry-title">${esc(e.title)}</div><div class="case-badge">${esc(id)}</div><div class="case-badge">Observed / recorded</div><p>${esc(EVIDENCE_INFO[id]?.meaning||'Evidence recorded')}</p><p><strong>Source:</strong> ${esc(e.source||'Direct observation')}</p></div>`).join('')||'<p>No evidence recorded yet. Inspect the shop clock and walls to begin.</p>':s.notes.slice(-55).reverse().map(n=>`<div class="entry"><div class="entry-title">${esc(n.at)}</div><p>${esc(n.text)}</p></div>`).join('')}`;
