function hearingLevel(g){return Number(!!g.evidence['EV-C11'])+Number(!!g.evidence['EV-C12'])+Number(!!g.flags.a4_independent_catalog_verified)+Number(!!g.evidence['EV-C14']);}
function caseStatus(){
 if(!s)return 'No active case yet.';
 const id=parts(s.scene).id,road=s.flags.chosen_road;
 if(id.startsWith('A8-')||id==='HUB-08')return 'You are close to the end of Book One. Use the clues you found and the help people freely offered. The ending you earn will become part of your Living Atlas.';
 if(id.startsWith('A7-')||id==='HUB-07'||['REC-06','REC-10','REC-12'].includes(id))return s.flags.a7_final_readiness_checked?'Your plan is ready, but the machine still runs. The bell can warn people; it cannot stop the machine for you. Protect every person’s right to choose.':'Find out what the bell can really do. Ask allies for help, and plan how to stop all three parts of the machine.';
 if(id.startsWith('A6-')||id==='HUB-06'||id==='REC-07')return s.flags.a6_directive_authenticated?'You found proof that the Margin King ordered today’s thefts. The Ink Thief can choose differently now, but still needs to repair the harm. Nobody has agreed to have an ending restored yet.':'Find the original order. Learn who sent it, and ask people what they want before making a plan.';
 if(id.startsWith('A5-')||id==='HUB-05'||['REC-08','REC-11'].includes(id))return s.flags.a5_verdict_supported?'The court found that pages were taken without permission. It still does not know who gave the current order. People who need privacy can keep it.':'The court has '+hearingLevel(s)+' different kinds of clues. Check the old seal and listen to witnesses. A person may choose not to speak.';
 if(id.startsWith('A4-')||id==='HUB-04'||id==='REC-05')return s.flags.a4_keeper_record_established&&s.evidence['EV-C11']&&s.evidence['EV-C12']?'The torn page, separate catalog, and checked order show that story pages were taken. We still do not know who ordered it or where the Lantern Keeper went.':'Check the torn page against records kept by different people. Keep private names safe.';
 if(id.startsWith('A3-')||id==='HUB-03'||['REC-04','REC-09'].includes(id))return s.flags.a3_gretel_ruling_supported?'Gretel found a copied mark and a changed date. The records support her finding. That does not mean Taffy made the fake.':'Compare Gretel’s calendar with Taffy’s original order. See which date and mark are real.';
 if(id.startsWith('A2-')||id==='HUB-02'||id.startsWith('REC-'))return s.flags.act2_keeper_appointment_authenticated?'You proved that a Lantern Keeper once worked at Crossing Three. Their name, location, and the person behind the theft are still unknown.':'The map and letter do not match. Visit another kingdom and check the crossing before deciding what happened.';
 if(road==='cloud')return s.evidence['EV-C05']?'Bram’s clock log and the village receipt show a missing day. Keep looking for who changed the records.':'Compare Bram’s clock log with a receipt from the village. Did a real day go missing from the record?';
 if(road==='palace')return s.evidence['EV-C07']&&s.evidence['EV-C08']?'The place setting and ceremony words were changed. This does not tell you who took the missing guest.':'Look at the chairs and the original ceremony words. Do not guess who is missing.';
 if(!s.evidence['EV-C03'])return 'The Wolf has been accused. Look at the real pawprints and the dark ink marks before deciding anything.';
 if(s.flags.grandmother_account||s.flags.courier_statement_recorded)return 'The footprints and witness accounts do not point to the Wolf. The person who made the false trail is still unknown.';
 return 'The false tracks do not match the Wolf’s paws. You still need more clues before naming who made them.';
}
function theoryFeedback(t){if(t==='plan_bell')return s.evidence['EV-C15']?'ESTABLISHED: the checked bell part confirms a warning, not an all-powerful machine switch.':'NEEDS VERIFICATION: look for the apprentice’s signed drawing or the original repair notes.';if(t==='plan_consent')return 'NOT SUPPORTED: possessing a page does not grant consent; Elowen may agree to one limited private test or decline.';if(t==='plan_safety')return s.flags.a7_counterplan_mapped?'SUPPORTED PLAN: the sorter, binder and road-cutter each have a way to stop it safely. Planning is not completion.':'WORKING PLAN: inspect the three dependencies and confirm the witness safeguards.';if(t==='plan_king')return 'CONTRADICTED: forcing one approved history caused the First White Silence; replacing the ruler would repeat the failure.';if(t==='margin_correct')return s.flags.a6_directive_authenticated?'SUPPORTED: current directive plus earlier clues that came from different places identify a present architect, while affected consent stays open.':'PROMISING HYPOTHESIS: check the original order and listen to the people it hurt.';if(['margin_bell','margin_thief','margin_elowen'].includes(t))return'NOT PROVEN: the bell is a warning, a kind act does not erase harm, and a name is not consent.';if(t==='court_withdrawals')return hearingLevel(s)>=3?'SUPPORTED: independent physical, catalog, order and correction sources support the pattern. The current author remains unidentified.':'PARTIALLY SUPPORTED: record the sources and check who kept each record.';if(t==='court_crown')return 'NOT PROVEN: the counterfeit symbol derives from the old Margin Office matrix, not the current sovereign’s personal seal.';if(t==='court_thief')return 'NOT SUPPORTED: refusing one harmful instruction shows that it may make choices, not that it is forgiven or that we know where it came from.';if(t==='court_absent')return 'FALSE: declining to testify is not guilt; the physical track comparison must stand separately.';if(t==='court_seal')return s.evidence['EV-C14']?'SUPPORTED: the copied crest belongs to an expired Margin Office, not a proven current royal signature.':'POSSIBLE: compare the old charter to independent current authorizations.';if(t==='court_person')return s.flags.a5_verdict_supported?'NOT ESTABLISHED: pages taken without permission are proven, but the individual author is still unknown.':'NOT PROVEN: a familiar name or prior mistake is not enough.';if(t==='archive_copies')return 'INCORRECT: A copy shares its parent source and is not independent approval.';if(t==='archive_order')return s.evidence['EV-C11']&&s.evidence['EV-C12']&&s.flags.a4_independent_catalog_verified?'SUPPORTED: Separate physical, catalog and order families support pages taken without permission; they do not identify the mastermind.':'POSSIBLE BUT NOT YET ESTABLISHED: check the original page, a different catalog, and the order before making this finding.';if(t==='archive_quill')return 'THAT DOES NOT FOLLOW FROM THE CLUES: Quill concealed an earlier child-protection amendment, not proof she authored the present theft campaign.';if(t==='archive_keeper')return 'INCORRECT: Crossing Three and a physical mark at the crossing support a real appointment even if a later register is blank.';if(t==='march_mark')return s.flags.a3_gretel_ruling_supported?'SUPPORTED: Gretel’s dates recorded by different people, the original purchase ledger and fiber test establish a copied mark. No culprit is named.':s.evidence['EV-C09']?'OBSERVED, NOT YET CERTIFIED: Continue the different dates and the paper itself.':'NOT YET SUPPORTED: First inspect the actual order and separate calendar.';if(t==='march_taffy')return 'NOT SUPPORTED: Owning the mark does not prove Taffy applied a later copied stamp.';if(t==='march_memory')return 'NOT SUPPORTED: A dangerous offer is not proof of an accepted trade or a missing witness identity.';if(t==='keeper_erased')return 'NOT SUPPORTED: Missing from a directory does not mean never existed.';if(t==='keeper_route')return s.evidence['EV-C10']?'SUPPORTED: The stitched route aligns with a second record kept by someone else and Crossing Three. It does not name a culprit.':'NOT YET ESTABLISHED: Seek a second region and compare the physical crossing.';if(t==='keeper_ink')return 'NOT SUPPORTED: A silver seam establishes a strange road, not who removed an ending.';if(t==='clock_time')return'NOT SUPPORTED: The weather clock counts possible travel dates; no one rewound their actual life.';
 if(t==='clock_gap')return s.evidence['EV-C05']?'SUPPORTED: Separate calendar and receipt records establish a missing date. The culprit remains unknown.':'NOT YET SUPPORTED: Compare separate records first.';
 if(t==='clock_bram')return'CONTRADICTED: Bram’s original agrees with an independent baker’s receipt.';
 if(t==='palace_guess')return'NOT PROVEN: A reflection cannot name a person, and private identities require consent.';
 if(t==='palace_invalid')return s.flags.palace_closure_invalid||s.flags.palace_midnight_released?'SUPPORTED: The imposed closing words were unauthorized and depended on the incomplete list.':'NOT YET SUPPORTED: Compare ceremony instructions and physical records.';
 if(t==='palace_cindy')return'NOT SUPPORTED: Her earlier limited protective edit is not proof she forged a different ceremony clause.';
 if(t==='wolf')return s.evidence['EV-C03']?'CONTRADICTED: The observed living paw does not match the ink impressions.':'NOT PROVEN: Compare the actual paws first.';
 if(t==='fake')return s.evidence['EV-C03']?'SUPPORTED: The physical tracks were artificial, but their maker is unknown.':'NOT YET ESTABLISHED: Compare the marks.';
 return'NOT PROVEN: The shifting ink shadow has not been identified.';}
function itemDescription(x){return({'Journal':'Records what you saw, what people chose to tell you, and the theories you have tested.','Stitched Map':'Remembers investigated roads. It does not reveal unseen places.','Silver Compass':'Points toward unanswered questions; cannot solve them for you.','Promise Ribbon':'A small reminder that consent and promises matter.','Old Key':'Fits an unknown old lock; it cannot replace evidence.','Borrowed Ribbon':'Loaned with an agreed return. You may not keep it without permission.','Return Thread':'Marks a verified seam back to the Midnight Bookshop.','Signed Route Terms':'Limited, fully fulfilled agreement for route information; no other person’s consent traded.'})[x]||'A safe keepsake or record collected during this investigation.';}
function getPref(k,f){const a=read('ouat-p5-prefs');return a&&Object.prototype.hasOwnProperty.call(a,k)?a[k]:f}
function setPref(k,v){const a=read('ouat-p5-prefs')||{};a[k]=v;write('ouat-p5-prefs',a);applyPrefs()}
function applyPrefs(){document.documentElement.style.setProperty('--size',getPref('scale',1));document.body.classList.toggle('high-contrast',getPref('contrast',false));document.body.classList.toggle('reduced-motion',getPref('reduced',false));if(window.OUATSound)OUATSound.setVolume(getPref('volume',.24));}
function exportSave(){
 if(!s){toast('No active adventure to export.');return}
 const prefs=read('ouat-p5-prefs')||{};const data=JSON.stringify(OUATSave.buildExport(s,meta,prefs),null,2);
 const blob=new Blob([data],{type:'application/json'});const a=document.createElement('a');const url=URL.createObjectURL(blob);
 a.href=url;a.download='once-upon-another-time-pass15-backup.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
 toast('Save + Living Atlas backup prepared');
}
function restoreLocal(candidate){
 if(!candidate||!confirm('Restore '+candidate.label+'? Your current in-progress adventure will be replaced. Export a backup first if needed.'))return;
 try{const old=localStorage.getItem(SAVE_KEY);if(old)try{OUATSave.sanitizeGame(JSON.parse(old),validScene);localStorage.setItem(SAVE_KEY+'.checkpoint',old)}catch{};
 s=OUATSave.sanitizeGame(candidate.game,validScene);recoveryIssue='';save();closeSheet();lastRenderedScene='';renderTitle();toast('Healthy save restored')}
 catch(e){byId('importResult')&&(byId('importResult').textContent='Restore failed: '+e.message)}
}
function restoreImported(data){
 if(!confirm('Replace this device’s current story and Living Atlas with the imported backup? Export your existing save first if you want to keep it.'))return;
 const priorS=s,priorMeta=meta;try{
  if(s)save();const old=localStorage.getItem(SAVE_KEY);if(old){try{OUATSave.sanitizeGame(JSON.parse(old),validScene);localStorage.setItem(SAVE_KEY+'.checkpoint',old)}catch{}}
  s=data.game;meta=data.profile;if(data.prefs)write('ouat-p5-prefs',data.prefs);
  if(!save())throw Error('Browser storage is full or unavailable.');
  recoveryIssue='';closeSheet();lastRenderedScene='';applyPrefs();renderTitle();toast('Imported backup restored');
 }catch(e){s=priorS;meta=priorMeta;byId('importResult')&&(byId('importResult').textContent='Restore failed: '+e.message)}
}

function renderFinish(){
 if(s.flags.act8_complete){renderBookOneFinish();return;}
 s.complete=true;const r=s.flags.chosen_road||'woods';if(!Array.isArray(meta.completedLocal))meta.completedLocal=[];if(!meta.completedLocal.includes(r))meta.completedLocal.push(r);save();byId('toast').className='';
 const routeText=({woods:'Neverafter Woods',cloud:'Cloudreach',palace:'Palace of Hours'})[r]||'the Storyfold';
 const stage7=!!s.flags.act7_complete,stage6=!!s.flags.act6_complete,stage5=!!s.flags.act5_complete,stage4=!!s.flags.act4_complete,stage3=!!s.flags.act3_complete,stage2=!!s.flags.act2_complete;
 const result=stage7?{title:'The Story That Chose You',label:'ACT VII · FINAL PREPARATION COMPLETE',summary:`Your coalition reached a legitimate preparation plan after the court and Margin investigation. You identified the warning bell’s true role, listened to affected witnesses, and prepared the three-part machine response. None of these achievements is yet a Book One ending.`,note:`Prepared strategy: ${s.flags.a7_strategy_requested||'ordinary defense'}. Party: ${s.flags.a7_travel_party||'still being organized'}. Elowen’s permission: ${s.flags.a7_affected_permission||'not recorded'}. The machine still operates; its resolution belongs to Act VIII.`}:stage6?{title:'Beyond the Last Page',label:'ACT VI · MARGIN INVESTIGATION · COMPLETE',summary:`You entered the Margin from ${routeText}, proved the Ink Thief’s shifting forms belong to one created being, and uncovered the current Safe Ending Directive. The King is responsible for the ongoing stolen-ending campaign—not the First White Silence.`,note:`Ink Thief response: ${s.flags.a6_thief_outcome||'unresolved'}. Machine mapped: ${s.flags.a6_machine_mapped?'yes':'not yet'}. Bringing an ending back requires an anchor, an alternative, and permission given after hearing the whole plan. The ending-stealing machine still runs.`}:stage5?{title:'The Court of Unwritten Endings',label:'ACT V · FAIR COURT · COMPLETE',summary:`The trial heard witnesses, separate original sources, and your ${routeText} history. The court entered bounded findings about pages taken without permission while leaving the current author and the Lantern Keeper’s fate unresolved.`,note:`Your court approach: ${s.flags.a5_verdict_style||'bounded'}. Accusation: ${s.flags.a5_accusation||'deferred'}. ${s.flags.a5_retraction?'A retraction was recorded.':'No retraction was recorded.'} The ending-stealing machine still operates beyond the page.`}:stage4?{title:'The Archive of Impossible Truths',label:'ACT IV · ROYAL ARCHIVE · COMPLETE',summary:`You brought the ${routeText} case, the Keeper’s route, and the forged date found in Gingerbread March into a fair Archive examination. You authenticated the missing-page fibers and Tern’s order without exposing protected witnesses.`,note:`Your court strategy is ${s.flags.a4_court_strategy||'proof-first'}. Quill has acknowledged her own secret amendment; the author of the present theft and the Keeper’s fate are still not established.`}:stage3?{title:'The Kingdom of Sweet Lies',label:'ACT III · GINGERBREAD MARCH · COMPLETE',summary:`You started in ${routeText}, followed the Lantern Keeper trail, and helped Gretel and Taffy establish that a correction was mechanically copied after the real purchase. Your ${s.flags.a3_archive_approach||'limited'} approach to the Royal Archive is recorded. The culprit and Keeper’s fate remain unproven.`,note:`The family kept its story, the corrected public record survives, and the ${s.flags.a3_crossing==='repair'?'sugarstone safety inspection':s.flags.a3_crossing==='ferry'?'safe ferry route':'public toll challenge'} will be remembered.`}:stage2?{title:'The Keeper’s Road',label:'ACT II · THE MISSING LANTERN KEEPER · COMPLETE',summary:`You began in ${routeText}. Crossing Three has an authentic keeper appointment, but no verified culprit.`,note:'Continue toward Gingerbread March from your current save.'}:{title:'Local Mystery Solved',label:'ACT I · LOCAL CASE COMPLETE',summary:`Your ${routeText} mystery is locally resolved.`,note:'Act II continues this investigation.'};
 root.innerHTML=`<main class="screen-cover" style="justify-content:flex-end"><div class="cover-heading"><div class="cover-logo">✦</div><h1 style="font-size:clamp(34px,9vw,50px)">${esc(result.title)}</h1><small>${esc(result.label)}</small></div><div class="cover-bottom"><div class="outcome"><h3>${stage7?'The companions are ready. The ending is still yours to earn.':stage6?'The machine is found. The story is not finished.':stage5?'A fair verdict changed the kingdom—but not the machinery.':stage4?'The court has a fair case to hear.':stage3?'The March has its own truthful account.':stage2?'You found the Keeper’s trail.':'You solved a local mystery.'}</h3><p>${esc(result.summary)}</p><p>${esc(result.note)}</p><p><strong>Evidence:</strong> ${Object.keys(s.evidence).length} clues<br><strong>Decisions:</strong> ${s.decisions}<br><strong>First kingdom:</strong> ${esc(routeText)}</p></div><div class="notice" style="margin-bottom:17px">${stage7?'Act VII is complete. Return to your adventure for Act VIII and the ending you can earn.':stage6?'Act VI is complete. Your next chapter is Act VII.':stage5?'The court case is complete. The adventure continues into Act VI.':stage4?'The Archive case is complete. Your next chapter is the royal court.':stage3?'The Gingerbread March case is complete. The Royal Archive is next.':stage2?'Return to your saved adventure to begin Act III.':'Your first kingdom mystery is solved. The Lantern Keeper case comes next.'}</div><div class="stack"><button class="btn primary" id="finishJournal">Review Your Journal <span class="arrow">❯</span></button><button class="btn" id="finishNew">Try Another Starting Kingdom <span class="arrow">↻</span></button><button class="btn subtle" id="finishTitle">Title Screen</button></div><p class="save-note">Your current telling stays saved locally until replaced. A new local route is not an in-world rewind or canonical New Game Plus.</p></div></main>`;
 byId('finishJournal').onclick=()=>showSheet('journal');byId('finishNew').onclick=()=>{if(!confirm('Start another local adventure? This replaces your current save, but keeps locally completed realms.'))return;meta.demoRuns++;save();renderSetup()};byId('finishTitle').onclick=renderTitle;
}
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&overlayType){e.preventDefault();closeSheet()}else trapSheetKeys(e)});load();applyPrefs();renderTitle();
